"""Render an offline Chromatic Field explorer from compact public search evidence.

No database, private pools, model services, or environment execution is used.
"""
import argparse
import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
INPUTS = ('lineage.json', 'generation-metrics.json', 'source-changes.json',
          'selection/selection.json', 'native-audit.json')


def load_evidence(directory):
    inputs = {name: json.loads((directory / name).read_text()) for name in INPUTS}
    rows = inputs['lineage.json']
    metrics = inputs['generation-metrics.json']
    changes = inputs['source-changes.json']
    selection = inputs['selection/selection.json']
    audit = inputs['native-audit.json']
    by_id = {r['id']: r for r in rows}
    by_generation = {r['generation']: r for r in metrics}
    assert len(by_id) == len(rows)
    assert len(by_generation) == len(metrics) == audit['persisted_slots']
    assert len(rows) == audit['native_rows_including_island_seed_copies']
    assert changes['lineage_sha256'] == hashlib.sha256((directory/'lineage.json').read_bytes()).hexdigest()
    for row in rows:
        assert row['generation'] in by_generation
        for linked in ([row['parent_id']] if row['parent_id'] else []) + row['archive_inspiration_ids'] + row['top_k_inspiration_ids']:
            assert linked in by_id
    assert by_id[selection['native_id']]['source_sha256'] == selection['selected_source_sha256']
    compact_rows = [{key: row[key] for key in (
        'id', 'generation', 'parent_id', 'birth_island', 'island_idx', 'correct',
        'source_sha256', 'archive_inspiration_ids', 'top_k_inspiration_ids', 'migration_history')}
        | {'operator': row['metadata'].get('patch_type', 'init')}
        for row in rows]
    compact_metrics = [{key: r.get(key) for key in (
        'generation', 'correct', 'combined_score', 'episode_count', 'escape', 'death',
        'timeout', 'invalid', 'brier_near', 'brier_audit', 'candidate_cpu_seconds')}
        for r in metrics]
    ranking = [{key: r[key] for key in ('slot', 'episodes', 'invalid', 'selection_escapes',
        'selection_task', 'selection_task_units', 'program_sha256')} for r in selection['ranking']]
    return {'rows': compact_rows, 'metrics': compact_metrics,
        'changes': changes['candidates'], 'change_scope': changes['scope'],
        'selection': {'generation': selection['generation'], 'native_id': selection['native_id'],
            'ranking': ranking, 'episodes': selection['condition_episodes'],
            'cases': selection['case_count'], 'selection_biased': selection['selection_biased']},
        'audit': {key: audit[key] for key in ('persisted_slots', 'native_rows_including_island_seed_copies',
            'valid_descendants', 'failed_slots', 'saved_evaluation_episodes', 'patch_application_failures',
            'patch_retry_attempts', 'native_model_requests', 'all_model_requests_including_probes',
            'model_requests_by_role', 'reported_tokens', 'resources', 'features', 'effective_model', 'effective_effort')},
        'rejected_attempts': [{key: attempt.get(key) for key in ('generation', 'patch_attempt', 'error_msg')}
                              for attempt in audit['patch_attempts'] if not attempt.get('success')],
        'inputs': [{'path': name, 'sha256': hashlib.sha256((directory/name).read_bytes()).hexdigest()}
                   for name in INPUTS]}


